import{Lt as e,Vt as t,Z as n,_t as r,bt as i,vt as a}from"./chunks/framework.CsLlEPF4.js";var o=JSON.parse(`{"title":"XML 基础","description":"","frontmatter":{"title":"XML 基础","date":"2022-08-01T16:23:04.000Z","updated":"2022-08-03T10:17:53.000Z"},"headers":[],"relativePath":"csl-dev-guide/xml-basic.md","filePath":"wiki/csl-dev-guide/xml-basic.md"}`),s={name:`csl-dev-guide/xml-basic.md`};function c(n,o,s,c,l,u){let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[o[0]||=a(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /csl-dev-guidexml-basic.md for this page in Markdown format</div><h1 id="xml-基础" tabindex="-1">XML 基础 <a class="header-anchor" href="#xml-基础" aria-label="Permalink to “XML 基础”">​</a></h1><p>CSL 是基于 XML 的，如果你不熟悉 XML，本章将带你了解编辑 CSL 样式及其本地化文件所需的 XML 基础知识。</p><h2 id="标记语言" tabindex="-1">标记语言 <a class="header-anchor" href="#标记语言" aria-label="Permalink to “标记语言”">​</a></h2><p>「标记语言」是计算机领域中的概念，抛开晦涩的概念定义，我们的书面语言其实就是使用标记的语言。我们会用逗号、句号、感叹号等标点符号来标记句子的停顿和结束，用括号来标记补充信息，用引号来标记句子中引用的内容。在标点符号的帮助下，连续的信息变得富有层次，无声的字符也能表示丰富的语气。</p><p>在其他场景中，学生们使用不同颜色的荧光笔来标记文本的不同内容，语言学家们使用成分符号来标记句子的语法成分（如主语、谓语、宾语等），编辑们使用校对符号来标记对文本的修订行为（如删除、添加、替换等）……</p><p>标记语言将信息记录为结构化的文本，从而使得计算机能够识别和处理这些信息。</p><h2 id="xml" tabindex="-1">XML <a class="header-anchor" href="#xml" aria-label="Permalink to “XML”">​</a></h2><p>XML（eXtensible Markup Language）是一种广泛使用的标记语言，结合下面的例子来看看 XML 的基本结构。</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;?</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">xml</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> encoding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utf-8&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> standalone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ?&gt;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">&lt;!-- 这是一个注释 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">child-one</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">child-two</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> attribute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;属性&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">child-one</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">child-tone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>下面，我们将逐行介绍这段代码。</p><ol><li>第一行称为声明，或者称为序言，总是在文档的最前面。包括了 XML 的版本、编码信息以及是否依赖外部文档等。实际编写 CSL 样式时，我们遵从的是同一套规则，只需从现有的样式文件中原封不动抄写这一行即可。</li><li>第二行是 XML 文档的注释，格式为 <code>&lt;!-- 注释内容--&gt;</code>。注释的位置比较自由，但需要单独成行。你可以在某一段代码上方概括下一段代码的主要作用。</li><li>剩下的代码为 XML 文件的主体部分，它由根元素及内部若干个子元素构成。</li></ol><p>上面的代码中，最明显的是像「 <code>&lt;xxx&gt;</code>」这样的内容，它就是 XML 的「标签」。作为一种通用的标记语言，XML 中要表示许许多多的成分，标签就像注明了名称的括号，一方面像括号一样选定一段内容，另一方面又通过它的名称来指示这是一段什么内容。相比上一节 <a href="#xml-基础">XML 基础</a> 中的例子，读者在不知道标签具体定义的情况下仅凭标签名就能大致推测该标记的含义，而且使用命名来区分标记也使标记不再局限于有限的标点符号，提高了标记的可读性和拓展性。</p><p>元素就是被标签标记起来的一块内容，一个 XML 文档必需有一个唯一的根元素（如例子中的 <code>root</code> 元素），根元素包含其他所有元素。当然，其他元素内也可以有子元素。例子第一个 <code>child-one</code> 元素内有其他元素，因此它是一个「开放」的元素，以开始标签<code>&lt;child-one&gt;</code> 和 结束标签 <code>&lt;/child-one&gt;</code>标记范围（正如括号那样需要成对使用）；而第二个 <code>child-tone</code> 元素没有子元素，因此它是一个「闭合」的元素，在同一个标签上开始和结束（正如逗号那样单独使用）。</p><p>属性写在标签名后，是对元素及其内容的描述，属性名和属性值之间用 <code>=</code> 隔开，属性值使用双引号 <code>&quot;</code> 包裹。每个元素中，一个属性最多出现一次，一个属性只能有一个值。</p><p>值得注意的是，标签已经使用空格作为标签名和属性之间的分隔符，标签名和属性名中不允许使用空格（否则会引起歧义）。我们通常使用「<a href="https://developer.mozilla.org/zh-CN/docs/Glossary/Kebab_case" target="_blank" rel="noreferrer">烤串命名法</a>」（kebab case）来命名标签名和属性名，即使用 <code>-</code> 来分隔一系列小写单词，如 <code>child-one</code>、<code>attribute-one</code>。</p><h2 id="实体" tabindex="-1">实体 <a class="header-anchor" href="#实体" aria-label="Permalink to “实体”">​</a></h2><p>在上一节我们了解到，XML 文档是由声明、元素和注释组成的，大量使用了 <code>&lt;</code> 和 <code>&gt;</code> 等字符，为了避免歧义，在确实需要表达类似这样的字符时，需用名为「实体」的代码来代替。</p><table tabindex="0"><thead><tr><th>所定义的实体</th><th>所代表的字符</th></tr></thead><tbody><tr><td><code>&amp;lt;</code></td><td><code>&lt;</code></td></tr><tr><td><code>&amp;gt;</code></td><td><code>&gt;</code></td></tr><tr><td><code>&amp;quot;</code></td><td><code>&quot;</code></td></tr><tr><td><code>&amp;apos;</code></td><td><code>&#39;</code></td></tr><tr><td><code>&amp;amp;</code></td><td><code>&amp;</code></td></tr></tbody></table><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Para1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;John asked </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;apos;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s your name?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Para1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">中间的结果:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">John asked &quot;What&#39;s your name? &quot;</span></span></code></pre></div>`,20),i(d),i(f)])}var l=n(s,[[`render`,c]]);export{o as __pageData,l as default};